:root {
  --bg: #1e1b2e;
  --card: #2a2740;
  --text: #f0edf7;
  --muted: #b3aecb;
  --accent: #7c6cf0;
  --accent-hover: #9184f5;
  --accent-pressed: #6553d9;
  --success: #4ade80;
  --error: #f87171;
  --border: #3d3858;
  --focus: #c4b5fd;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: var(--bg);
  background-image: radial-gradient(circle at 20% 20%, #2e2a4a 0%, transparent 40%),
                    radial-gradient(circle at 80% 80%, #2a2740 0%, transparent 40%);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

.card {
  width: 100%;
  max-width: 520px;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
}

h1 {
  margin: 0 0 4px;
  font-size: 1.5rem;
  letter-spacing: -0.01em;
}

.subtitle {
  margin: 0 0 20px;
  color: var(--muted);
  font-size: 1rem;
}

.field {
  margin-bottom: 16px;
}

label {
  display: block;
  margin-bottom: 6px;
  font-weight: 600;
  font-size: 1rem;
}

input[type="text"] {
  width: 100%;
  padding: 10px 12px;
  font: inherit;
  color: var(--text);
  background: #1e1b2e;
  border: 1px solid var(--border);
  border-radius: 8px;
  transition: border-color 0.15s, box-shadow 0.15s;
}

input[type="text"]::placeholder {
  color: #7c7799;
}

input[type="text"]:hover {
  border-color: #5a5380;
}

input[type="text"]:focus-visible {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(196, 181, 253, 0.3);
}

.primary {
  display: inline-block;
  width: 100%;
  padding: 12px 16px;
  margin-top: 4px;
  font: inherit;
  font-weight: 700;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
}

.primary:hover {
  background: var(--accent-hover);
}

.primary:active {
  background: var(--accent-pressed);
  transform: translateY(1px);
}

.primary:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.result {
  margin-top: 20px;
  padding: 14px 16px;
  border-radius: 8px;
  background: #1e1b2e;
  border: 1px solid var(--border);
  font-size: 1rem;
  min-height: 52px;
  display: flex;
  align-items: center;
}

.result.success {
  border-color: var(--success);
  color: var(--success);
}

.result.error {
  border-color: var(--error);
  color: var(--error);
}

.history-section {
  margin-top: 24px;
}

h2 {
  margin: 0 0 10px;
  font-size: 1.1rem;
  color: var(--muted);
  font-weight: 600;
}

.history-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.history-list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  background: #1e1b2e;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.95rem;
  word-break: break-word;
}

.history-list li .pair {
  color: var(--muted);
  flex: 1;
  min-width: 0;
}

.history-list li .verdict {
  font-weight: 700;
  white-space: nowrap;
}

.history-list li .verdict.yes {
  color: var(--success);
}

.history-list li .verdict.no {
  color: var(--error);
}

.history-list li.empty {
  color: var(--muted);
  justify-content: center;
  font-style: italic;
}

@media (max-width: 400px) {
  .card {
    padding: 18px;
  }
  h1 {
    font-size: 1.3rem;
  }
  .history-list li {
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
  }
}

const form = document.getElementById('anagram-form');
const inputA = document.getElementById('input-a');
const inputB = document.getElementById('input-b');
const resultEl = document.getElementById('result');
const historyList = document.getElementById('history-list');

const MAX_HISTORY = 5;
let history = [];

function normalize(text) {
  return text.replace(/\s+/g, '').toLowerCase();
}

function isAnagram(a, b) {
  const na = normalize(a);
  const nb = normalize(b);
  if (na.length !== nb.length) return false;
  const counts = new Map();
  for (const ch of na) {
    counts.set(ch, (counts.get(ch) || 0) + 1);
  }
  for (const ch of nb) {
    const c = counts.get(ch);
    if (!c) return false;
    counts.set(ch, c - 1);
  }
  return true;
}

function renderResult(ok, a, b) {
  resultEl.classList.remove('success', 'error');
  const textEl = resultEl.querySelector('.result-text');
  if (ok) {
    resultEl.classList.add('success');
    textEl.textContent = `Yes! "${a}" and "${b}" are anagrams.`;
  } else {
    resultEl.classList.add('error');
    textEl.textContent = `No, "${a}" and "${b}" are not anagrams.`;
  }
}

function renderHistory() {
  historyList.innerHTML = '';
  if (history.length === 0) {
    const li = document.createElement('li');
    li.className = 'empty';
    li.textContent = 'No checks yet.';
    historyList.appendChild(li);
    return;
  }
  for (const entry of history) {
    const li = document.createElement('li');
    const pair = document.createElement('span');
    pair.className = 'pair';
    pair.textContent = `"${entry.a}" / "${entry.b}"`;
    const verdict = document.createElement('span');
    verdict.className = 'verdict ' + (entry.ok ? 'yes' : 'no');
    verdict.textContent = entry.ok ? 'Anagram' : 'Not anagram';
    li.appendChild(pair);
    li.appendChild(verdict);
    historyList.appendChild(li);
  }
}

function addHistory(a, b, ok) {
  history.unshift({ a, b, ok });
  if (history.length > MAX_HISTORY) {
    history = history.slice(0, MAX_HISTORY);
  }
  renderHistory();
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  const a = inputA.value.trim();
  const b = inputB.value.trim();
  if (a === '' || b === '') {
    resultEl.classList.remove('success', 'error');
    resultEl.querySelector('.result-text').textContent = 'Please fill in both text boxes.';
    return;
  }
  const ok = isAnagram(a, b);
  renderResult(ok, a, b);
  addHistory(a, b, ok);
});

renderHistory();
